package dev.zomboid.tacz;public class Flow {static int n;static void check(boolean b){if(!b)throw new AssertionError(n);n++;}public static class Event {public double fov=70;public boolean configured=true;public boolean usedConfiguredFov(){return configured;}public Camera getCamera(){return new Camera();}public double getPartialTick(){return .5;}public double getFOV(){return fov;}public void setFOV(double f){fov=f;}}public static class Camera {public Object getEntity(){return Bridge.MC.player;}}public static void main(String[] args){Event e=new Event();ScopeZoom.apply(e);check(Math.abs(e.fov-ScopeZoom.fov(70,4,1))<1e-8);Bridge.MC.player.zoom=25;e=new Event();ScopeZoom.apply(e);check(Math.abs(e.fov-ScopeZoom.fov(70,25,1))<1e-8);Bridge.MC.player.progress=0;e=new Event();ScopeZoom.apply(e);check(e.fov==70);Bridge.MC.player.progress=2;e=new Event();ScopeZoom.apply(e);check(Math.abs(e.fov-ScopeZoom.fov(70,25,1))<1e-8);Bridge.iso=true;e=new Event();ScopeZoom.apply(e);check(e.fov==70);Bridge.iso=false;e=new Event();e.configured=false;ScopeZoom.apply(e);check(e.fov==70);Bridge.MC.player.gun=false;e=new Event();ScopeZoom.apply(e);check(e.fov==70);Bridge.MC.player=null;e=new Event();ScopeZoom.apply(e);check(e.fov==70);System.out.println("Scope API flow checks: "+n);}}
